let state = global.get('farm_state') || context.get('farm_state') || {
  online: true,
  stateText: 'S1_MONITOR',
  modeText: 'AUTO',
  reasonText: 'Dang giam sat on dinh',
  stateColor: '#0284c7',
  pumpActive: false,
  p1: false, p2: false, p3: false,
  z1_val: 50, z2_val: 50, z3_val: 50,
  weather_temp: 20.2, weather_hum: 98,
  dht_temp: 24.0, dht_hum: 40.0,
  max_prob: 36, eff_precip: 0.0, rainDelay: false,
  location: 'Cau Dat - Da Lat (Lam Dong)',
  isAlert: false, alertTitle: 'HE THONG AN TOAN', alertDetail: 'Cac vung dat dat do am chuan',
  weatherSource: 'LIVE OPEN-METEO'
};

const topic = msg.topic || '';

// A. Xu ly chuyen doi che do (AUTO / MANUAL)
if (msg.mode !== undefined) {
  state.modeText = msg.mode;
  if (state.modeText === 'MANUAL') {
    state.stateText = 'S6_MANUAL';
    state.stateColor = '#d97706';
    state.reasonText = 'Che do dieu khien thu cong';
    state.p1 = false; state.p2 = false; state.p3 = false; state.pumpActive = false;
  } else {
    state.stateText = 'S1_MONITOR';
    state.stateColor = '#0284c7';
    state.reasonText = 'Che do tu dong (AUTO)';
  }
} else if (msg.payload && msg.payload.mode !== undefined) {
  state.modeText = msg.payload.mode;
  if (state.modeText === 'MANUAL') {
    state.stateText = 'S6_MANUAL';
    state.stateColor = '#d97706';
    state.reasonText = 'Che do dieu khien thu cong';
    state.p1 = false; state.p2 = false; state.p3 = false; state.pumpActive = false;
  } else {
    state.stateText = 'S1_MONITOR';
    state.stateColor = '#0284c7';
    state.reasonText = 'Che do tu dong (AUTO)';
  }
}

// B. Xu ly Reset hoac Tiem su co
if (msg.payload && (msg.payload.fault === 'CLEAR_FAULT' || msg.payload.fault === 'RESET')) {
  state.isAlert = false;
  state.alertTitle = 'HE THONG DA PHUC HOI';
  state.alertDetail = 'Da xoa toan bo loi mo phong. He thong tro ve trang thai giam sat binh thuong.';
  state.stateText = (state.modeText === 'MANUAL') ? 'S6_MANUAL' : 'S1_MONITOR';
  state.stateColor = (state.modeText === 'MANUAL') ? '#d97706' : '#0284c7';
} else if (msg.payload && msg.payload.fault === 'D1_SOIL_FAIL') {
  state.isAlert = true;
  state.alertTitle = 'CANH BAO: HONG CAM BIEN DAT (D1)';
  state.alertDetail = 'Phat hien dut day / hong cam bien (SENSOR_RANGE). Chuyen trang thai S99_SAFE ngat bom.';
  state.stateText = 'S99_SAFE';
  state.stateColor = '#dc2626';
  state.p1 = false; state.p2 = false; state.p3 = false; state.pumpActive = false;
} else if (msg.payload && msg.payload.fault === 'D2_PUMP_JAM') {
  state.isAlert = true;
  state.alertTitle = 'CANH BAO: KET VAN / HONG BOM (D2)';
  state.alertDetail = 'Phat hien ket van co hoc hoac hong ro-le bom. Ngat toan bo bom dam bao an toan S99_SAFE.';
  state.stateText = 'S99_SAFE';
  state.stateColor = '#dc2626';
  state.p1 = false; state.p2 = false; state.p3 = false; state.pumpActive = false;
}

// C. Xu ly Tat tat ca bom (Emergency Stop / Mode Switch)
if (msg.payload && (msg.payload.zone === 0 || msg.payload.all === true) && (msg.payload.action === 'OFF' || msg.payload.cmd === 'OFF')) {
  state.p1 = false; state.p2 = false; state.p3 = false; state.pumpActive = false;
}

// D. Xu ly du lieu Topic MQTT
// 1. Do am Z1, Z2, Z3
if (topic.includes('z1/soil') || (msg.payload && msg.payload.zone === 1 && msg.payload.moisture !== undefined)) {
  const v = msg.payload.moisture !== undefined ? msg.payload.moisture : Number(msg.payload);
  state.z1_val = Math.max(0, Math.min(100, Math.round(v)));
} else if (topic.includes('z2/soil') || (msg.payload && msg.payload.zone === 2 && msg.payload.moisture !== undefined)) {
  const v = msg.payload.moisture !== undefined ? msg.payload.moisture : Number(msg.payload);
  state.z2_val = Math.max(0, Math.min(100, Math.round(v)));
} else if (topic.includes('z3/soil') || (msg.payload && msg.payload.zone === 3 && msg.payload.moisture !== undefined)) {
  const v = msg.payload.moisture !== undefined ? msg.payload.moisture : Number(msg.payload);
  state.z3_val = Math.max(0, Math.min(100, Math.round(v)));
}
// 2. DHT22 vi khi hau tai cho
else if (topic.includes('env')) {
  if (msg.payload.temperature !== undefined) state.dht_temp = Number(msg.payload.temperature);
  if (msg.payload.humidity !== undefined) state.dht_hum = Number(msg.payload.humidity);
}
// 3. Du bao thoi tiet
else if (topic.includes('weather')) {
  if (msg.payload.max_prob !== undefined) state.max_prob = msg.payload.max_prob;
  if (msg.payload.eff_precip !== undefined) state.eff_precip = msg.payload.eff_precip;
  if (msg.payload.weather_temp !== undefined) state.weather_temp = Number(msg.payload.weather_temp);
  else if (msg.payload.temp !== undefined) state.weather_temp = Number(msg.payload.temp);
  else if (msg.payload.temperature !== undefined) state.weather_temp = Number(msg.payload.temperature);

  if (msg.payload.weather_hum !== undefined) state.weather_hum = Number(msg.payload.weather_hum);
  else if (msg.payload.hum !== undefined) state.weather_hum = Number(msg.payload.hum);
  else if (msg.payload.humidity !== undefined) state.weather_hum = Number(msg.payload.humidity);

  if (msg.payload.location) state.location = msg.payload.location;
  state.rainDelay = (state.max_prob >= 70 && state.eff_precip >= 5.0) || msg.payload.heavy_rain === true;
  state.weatherSource = msg.payload.source || 'LIVE OPEN-METEO';
}
// 4. FSM State
else if (topic.includes('state')) {
  state.stateText = msg.payload.state || 'S1_MONITOR';
  state.modeText = msg.payload.mode || state.modeText;
  state.reasonText = msg.payload.reason || 'Dang giam sat on dinh';
  if (state.stateText.includes('RAIN') || state.stateText.includes('S3')) state.stateColor = '#2563eb';
  else if (state.stateText.includes('IRRIG') || state.stateText.includes('S4') || state.stateText.includes('S2')) state.stateColor = '#059669';
  else if (state.stateText.includes('SOAK') || state.stateText.includes('S9')) state.stateColor = '#d97706';
  else if (state.stateText.includes('SAFE') || state.stateText.includes('ERROR')) state.stateColor = '#dc2626';
  else if (state.stateText.includes('MANUAL') || state.stateText.includes('S6')) state.stateColor = '#d97706';
  else state.stateColor = '#0284c7';
}
// 5. Bom
else if (topic.includes('pump')) {
  const z = msg.payload.zone || 1;
  const on = (msg.payload.status === 'ON' || msg.payload.action === 'ON' || msg.payload.on === true);
  if (z === 1) state.p1 = on;
  else if (z === 2) state.p2 = on;
  else if (z === 3) state.p3 = on;
  state.pumpActive = (state.p1 || state.p2 || state.p3);
}
// 6. Online/Offline
else if (topic.includes('status')) {
  state.online = (msg.payload === 'online');
}
// 7. Alert
else if (topic.includes('alert')) {
  state.isAlert = true;
  state.alertTitle = 'CANH BAO: ' + (msg.payload.alert || 'SU CO VUNG ' + (msg.payload.zone || ''));
  state.alertDetail = msg.payload.detail || 'Phat hien trang thai bat thuong';
}

function evalZone(val, dry, wet, flood) {
  if (flood && val >= flood) {
    return { color: '#7c3aed', border: '#6d28d9', txt: '#6d28d9', badge_bg: '#ede9fe', badge_txt: '#5b21b6', status: 'NGAP UNG (>=80%)' };
  }
  if (val < dry) {
    return { color: '#ef4444', border: '#b91c1c', txt: '#b91c1c', badge_bg: '#fee2e2', badge_txt: '#991b1b', status: 'KHO - CAN TUOI' };
  }
  if (val <= wet) {
    return { color: '#10b981', border: '#047857', txt: '#047857', badge_bg: '#d1fae5', badge_txt: '#065f46', status: 'DU AM LY TUONG' };
  }
  return { color: '#0284c7', border: '#0369a1', txt: '#0369a1', badge_bg: '#e0f2fe', badge_txt: '#075985', status: 'AM CAO' };
}

const e1 = evalZone(state.z1_val, 40, 60, null);
const e2 = evalZone(state.z2_val, 40, 60, null);
const e3 = evalZone(state.z3_val, 35, 55, 80);

state.z1_color = e1.color; state.z1_border = e1.border; state.z1_txt = e1.txt; state.z1_badge_bg = e1.badge_bg; state.z1_badge_txt = e1.badge_txt; state.z1_status = e1.status;
state.z2_color = e2.color; state.z2_border = e2.border; state.z2_txt = e2.txt; state.z2_badge_bg = e2.badge_bg; state.z2_badge_txt = e2.badge_txt; state.z2_status = e2.status;
state.z3_color = e3.color; state.z3_border = e3.border; state.z3_txt = e3.txt; state.z3_badge_bg = e3.badge_bg; state.z3_badge_txt = e3.badge_txt; state.z3_status = e3.status;
state.anyPump = state.pumpActive;
state.isSoakWait = state.stateText.includes('SOAK') || state.stateText.includes('S9');

if (state.z3_val >= 80) {
  state.isAlert = true;
  state.alertTitle = 'CANH BAO: VUNG 3 (TRUNG) BI NGAP UNG!';
  state.alertDetail = 'Do am ' + state.z3_val + '% >= 80%. Da khoa van Z3 de chong ngap thung lung.';
} else if (state.isSoakWait) {
  state.isAlert = false;
  state.alertTitle = 'TRANG THAI: DANG NGHI NGAM (SOAK_WAIT)';
  state.alertDetail = 'Nuoc tu vung cao dang ngam dan xuong tang re va vung trung. Tam ngat bom de tranh chay tran xoi mon.';
} else if (state.z1_val < 40 || state.z2_val < 40 || state.z3_val < 35) {
  state.isAlert = true;
  const dryZones = [];
  if (state.z1_val < 40) dryZones.push('Zone 1: Vung cao (' + state.z1_val + '%)');
  if (state.z2_val < 40) dryZones.push('Zone 2: Vung giua (' + state.z2_val + '%)');
  if (state.z3_val < 35) dryZones.push('Zone 3: Vung trung (' + state.z3_val + '%)');
  state.alertTitle = 'CANH BAO DAT KHO: ' + dryZones.join(' | ');
  state.alertDetail = state.rainDelay ? 'Dang hoan tuoi vi sap co mua lon hieu dung (P_eff >= 5mm).' : 'He thong tu dong kich hoat tuoi tuan tu tu cao xuong thap (Z1 -> Z2 -> Z3).';
} else if (state.rainDelay) {
  state.isAlert = false;
  state.alertTitle = 'THONG BAO: DANG HOAN TUOI TU DONG';
  state.alertDetail = 'Du bao co mua lon (P_max ' + state.max_prob + '%, P_eff ' + state.eff_precip + 'mm). Tam dung bom de tiet kiem nuoc.';
} else {
  state.isAlert = false;
  state.alertTitle = 'HE THONG AN TOAN - DO AM DAT CHUAN';
  state.alertDetail = 'Ca 3 vung dat deu dang o trang thai du am ly tuong. Bom dang tat.';
}

context.set('farm_state', state);
global.set('farm_state', state);
msg.payload = state;
Object.assign(msg, state);
return msg;

msg.payload = {
  zone: 1,
  dry: msg.topic === 'dry_z1' ? Number(msg.payload) : undefined,
  wet: msg.topic === 'wet_z1' ? Number(msg.payload) : undefined
};
return msg;

let data = msg.payload;
if (typeof data === 'string') {
    try {
        data = JSON.parse(data);
    } catch (e) {
        node.warn('Khong the parse JSON tu Open-Meteo: ' + e.message);
    }
}

const locName = msg.locationName || 'Cau Dat - Da Lat (Lam Dong)';

function getRegionFallback(name) {
    if (name.includes('Long Khanh')) return { temp: 26.6, hum: 90, prob: 20, rain: 0.0 };
    if (name.includes('Buon Ma Thuot')) return { temp: 27.6, hum: 76, prob: 42, rain: 0.0 };
    if (name.includes('Cao Phong')) return { temp: 30.8, hum: 56, prob: 0, rain: 0.0 };
    if (name.includes('Cu Chi')) return { temp: 28.4, hum: 83, prob: 29, rain: 0.5 };
    return { temp: 20.2, hum: 98, prob: 36, rain: 0.0 }; // Cau Dat - Da Lat
}

let isLive = true;
let probs = [];
let rains = [];
let temps = [];
let hums = [];
let curTemp = 20.2;
let curHum = 98;
let maxP = 0;
let effP = 0.0;
let heavy = false;

function getK(r) {
    if (r < 2.0) return 0.15;
    if (r < 5.0) return 0.50;
    if (r < 10.0) return 0.80;
    return 0.50;
}

if (!data || typeof data !== 'object' || (!data.hourly && !data.current) || data.error) {
    isLive = false;
    const fb = getRegionFallback(locName);
    curTemp = fb.temp;
    curHum = fb.hum;
    maxP = fb.prob;
    effP = fb.rain;
    probs = [fb.prob, fb.prob, fb.prob];
    rains = [0, 0, 0];
    temps = [fb.temp, fb.temp, fb.temp];
    hums = [fb.hum, fb.hum, fb.hum];
    node.warn('Open-Meteo tam thoi khong phan hoi. Su dung thong so khi hau khu vuc ' + locName + ' (T=' + curTemp + 'C, H=' + curHum + '%)');
} else {
    const cur = data.current || {};
    const hourly = data.hourly || {};

    probs = hourly.precipitation_probability || [];
    rains = hourly.precipitation || [];
    temps = hourly.temperature_2m || [];
    hums = hourly.relative_humidity_2m || [];

    for (let i = 0; i < 3; i++) {
        const p = probs[i] !== undefined ? probs[i] : 0;
        const r = rains[i] !== undefined ? rains[i] : 0.0;
        if (p > maxP) maxP = p;
        effP += (r * getK(r));
        if (r >= 10.0) heavy = true;
    }

    if (cur.temperature_2m !== undefined) {
        curTemp = Number(cur.temperature_2m);
    } else if (temps.length > 0 && temps[0] !== undefined) {
        curTemp = Number(temps[0]);
    }

    if (cur.relative_humidity_2m !== undefined) {
        curHum = Number(cur.relative_humidity_2m);
    } else if (hums.length > 0 && hums[0] !== undefined) {
        curHum = Number(hums[0]);
    }
}

const weatherPayload = {
    source: isLive ? 'LIVE_OPEN_METEO' : 'REGION_PROFILE',
    location: locName,
    latitude: msg.latitude || '11.8500',
    longitude: msg.longitude || '108.5300',
    timestamp: Date.now(),
    max_prob: maxP,
    eff_precip: Number(effP.toFixed(2)),
    heavy_rain: heavy,
    weather_temp: curTemp,
    weather_hum: curHum,
    temperature: curTemp,
    humidity: curHum,
    temp: curTemp,
    hum: curHum,
    precipitation_probability: probs.slice(0, 3),
    precipitation: rains.slice(0, 3),
    temperature_2m: temps.slice(0, 3),
    relative_humidity_2m: hums.slice(0, 3)
};

node.status({ fill: isLive ? 'green' : 'yellow', shape: 'dot', text: locName + ': ' + curTemp + 'C | ' + curHum + '% | P_max:' + maxP + '%' });

return [
    { topic: 'g11/irrig/weather', payload: weatherPayload },
    { topic: 'g11/irrig/sim/weather', payload: weatherPayload }
];

let locStr = msg.payload;
if (typeof locStr !== 'string' || !locStr.includes(',')) {
    locStr = global.get('current_farm_loc') || "11.8500,108.5300,Cau Dat - Da Lat (Lam Dong)";
} else {
    global.set('current_farm_loc', locStr);
}

const parts = locStr.split(',');
const lat = parts[0].trim();
const lon = parts[1].trim();
const name = parts[2] ? parts[2].trim() : "Cau Dat - Da Lat (Lam Dong)";

msg.url = "https://api.open-meteo.com/v1/forecast?latitude=" + lat + "&longitude=" + lon + "&current=temperature_2m,relative_humidity_2m,precipitation,weather_code&hourly=temperature_2m,relative_humidity_2m,precipitation_probability,precipitation&timezone=Asia%2FHo_Chi_Minh";
msg.headers = {
    "User-Agent": "SmartFarm-IoT-G11/1.0 (nhom11.iot.project@student.edu.vn)"
};
msg.locationName = name;
msg.latitude = lat;
msg.longitude = lon;
node.status({ fill: "blue", shape: "dot", text: name });
return msg;

const state = global.get('farm_state') || {};
const trig = msg.payload;
let zone = 1;
if (trig === 'toggle_2') zone = 2;
if (trig === 'toggle_3') zone = 3;

let curState = false;
if (zone === 1) curState = !!state.p1;
else if (zone === 2) curState = !!state.p2;
else if (zone === 3) curState = !!state.p3;

const nextAction = curState ? "OFF" : "ON";
const outPayload = {
    zone: zone,
    action: nextAction,
    cmd: nextAction,
    ttl: 600
};

// Cap nhat state tuc thi
if (zone === 1) state.p1 = (nextAction === 'ON');
else if (zone === 2) state.p2 = (nextAction === 'ON');
else if (zone === 3) state.p3 = (nextAction === 'ON');
state.pumpActive = (state.p1 || state.p2 || state.p3);
global.set('farm_state', state);

node.status({ fill: nextAction === 'ON' ? 'green' : 'grey', shape: 'dot', text: 'Z' + zone + ' -> ' + nextAction });

return [
    { topic: "g11/irrig/cmd/pump", payload: outPayload },
    { topic: "g11/irrig/z" + zone + "/pump", payload: { zone: zone, status: nextAction, on: (nextAction === 'ON'), runtime: 0 } }
];

const data = msg.payload;
const probs = (data.hourly && data.hourly.precipitation_probability) ? data.hourly.precipitation_probability : [5, 5, 5];
const rains = (data.hourly && data.hourly.precipitation) ? data.hourly.precipitation : [0, 0, 0];
const temps = (data.hourly && data.hourly.temperature_2m) ? data.hourly.temperature_2m : [28, 28, 28];

let maxP = 0;
let effP = 0.0;
let heavy = false;

function getK(r) {
    if (r < 2.0) return 0.15;
    if (r < 5.0) return 0.50;
    if (r < 10.0) return 0.80;
    return 0.50;
}

for (let i = 0; i < 3; i++) {
    const p = probs[i] !== undefined ? probs[i] : 0;
    const r = rains[i] !== undefined ? rains[i] : 0.0;
    if (p > maxP) maxP = p;
    effP += (r * getK(r));
    if (r >= 10.0) heavy = true;
}

const curTemp = temps[0] || 25.0;
const scTopic = msg.topic || "";
let scName = "Mo phong thoi tiet";
if (scTopic === 'W0') scName = "W0: Nang rao (0mm)";
else if (scTopic === 'W1') scName = "W1: Mua rao (8mm)";
else if (scTopic === 'W2') scName = "W2: Mua phun (1mm)";
else if (scTopic === 'W3') scName = "W3: Mua lon (15mm/h)";
else if (scTopic === 'W4') scName = "W4: Han kiet (<25%)";
else if (scTopic === 'W5') scName = "W5: Du bao sai (Het mua)";

const weatherPayload = {
    source: "SIM_INJECT: " + scName,
    location: "Kich ban: " + scName,
    max_prob: maxP,
    eff_precip: Number(effP.toFixed(2)),
    heavy_rain: heavy,
    weather_temp: curTemp,
    temperature: curTemp,
    temp: curTemp,
    weather_hum: (maxP >= 70 ? 95 : 60),
    precipitation_probability: probs.slice(0, 3),
    precipitation: rains.slice(0, 3),
    temperature_2m: temps.slice(0, 3)
};

const out1 = { topic: "g11/irrig/sim/weather", payload: data };
const out2 = { topic: "g11/irrig/weather", payload: weatherPayload };
let out3 = null;

if (scTopic === 'W4') {
    out3 = { topic: "g11/irrig/sim/fault", payload: { fault: "W4_DROUGHT", zone: 1, moisture: 20 } };
} else if (scTopic === 'W0') {
    out3 = { topic: "g11/irrig/sim/fault", payload: { fault: "CLEAR_FAULT" } };
}

return [out1, out2, out3];
